mapper.select:



        AND EXISTS (
            SELECT 1 FROM breed_seed_distribute_detail d
            WHERE d.distribute_id = m.distribute_id
            AND d.breed_seed_produce_batch_id = #{query.breedSeedProduceBatchId}
        )


        AND EXISTS (
            SELECT 1 FROM breed_seed_distribute_detail d
            WHERE d.distribute_id = m.distribute_id
            AND d.crop_type = #{query.cropType}
        )


        AND EXISTS (
            SELECT 1 FROM breed_seed_distribute_detail d
            INNER JOIN breed_seed_produce p ON d.breed_seed_produce_batch_id = p.breed_seed_produce_batch_id
            WHERE d.distribute_id = m.distribute_id
            AND p.variety_id = #{query.varietyId}
        )


        AND DATE(m.time) >= #{query.startTime}


        AND DATE(m.time) <= #{query.endTime}


ORDER BY m.create_time DESC
